function() {
  var c = {{DL - ecommerce.currency}};
  if (typeof c === 'string' && c.length === 3) { return c.toUpperCase(); }
  return {{Const - Default Currency}};
}

function() {
  // Digits only, no leading zero, country code prefixed -> 966XXXXXXXXX.
  // Shared by the hash and the fallback transaction id so both agree
  // whether the visitor arrived with 05xxxxxxxx or 5xxxxxxxx.
  var raw = {{URL - phone param}};
  if (!raw) { return undefined; }
  var digits = String(raw).replace(/\D/g, '').replace(/^0+/, '');
  if (!digits) { return undefined; }
  var cc = {{Const - Country Code}};
  if (digits.indexOf(cc) !== 0) { digits = cc + digits; }
  return digits;
}

function() {
  var t = {{DL - ecommerce.transaction_id}};
  if (t) { return String(t); }
  // No order id available: derive a stable one from the normalised phone + day,
  // so a refresh reuses the same id and the platforms de-duplicate it.
  var p = {{JS - Phone (normalised)}};
  if (!p) { return undefined; }
  var d = new Date();
  var day = '' + d.getUTCFullYear()
    + ('0' + (d.getUTCMonth() + 1)).slice(-2)
    + ('0' + d.getUTCDate()).slice(-2);
  return 'hy-' + p + '-' + day;
}

function() {
  // Shared by Meta / TikTok / Snap so a refresh (or a future CAPI feed)
  // is de-duplicated instead of counted twice.
  var e = {{DL - event_id}};
  if (e) { return String(e); }
  var t = {{JS - Transaction ID}};
  return t ? String(t) : undefined;
}

function() {
  // 1) Prefer the hash computed server-side by the Hayak Pixel DataLayer plugin.
  var u = {{DL - user_data}};
  if (u && typeof u.sha256_phone_number === 'string' && u.sha256_phone_number.length === 64) {
    return u.sha256_phone_number;
  }
  // 2) Otherwise hash the normalised phone from the thank-you URL.
  //    Self-contained SHA-256 - no CryptoJS, so there is no load-order race.
  var digits = {{JS - Phone (normalised)}};
  if (!digits) { return undefined; }

  function sha256(ascii) {
    function rr(v, a) { return (v >>> a) | (v << (32 - a)); }
    var mm = Math.pow, maxWord = mm(2, 32), i, j, result = '';
    var words = [], asciiBitLength = ascii.length * 8;
    var hash = [], k = [], primeCounter = 0, isComposite = {};
    for (var candidate = 2; primeCounter < 64; candidate++) {
      if (!isComposite[candidate]) {
        for (i = 0; i < 313; i += candidate) { isComposite[i] = candidate; }
        hash[primeCounter] = (mm(candidate, 0.5) * maxWord) | 0;
        k[primeCounter++] = (mm(candidate, 1 / 3) * maxWord) | 0;
      }
    }
    ascii += '\x80';
    while (ascii.length % 64 - 56) { ascii += '\x00'; }
    for (i = 0; i < ascii.length; i++) {
      j = ascii.charCodeAt(i);
      if (j >> 8) { return null; }
      words[i >> 2] |= j << ((3 - i) % 4) * 8;
    }
    words[words.length] = (asciiBitLength / maxWord) | 0;
    words[words.length] = asciiBitLength;
    for (j = 0; j < words.length;) {
      var w = words.slice(j, j += 16), oldHash = hash;
      hash = hash.slice(0, 8);
      for (i = 0; i < 64; i++) {
        var w15 = w[i - 15], w2 = w[i - 2];
        var a = hash[0], e = hash[4];
        var temp1 = hash[7]
          + (rr(e, 6) ^ rr(e, 11) ^ rr(e, 25))
          + ((e & hash[5]) ^ ((~e) & hash[6]))
          + k[i]
          + (w[i] = (i < 16) ? w[i] : (
              w[i - 16]
              + (rr(w15, 7) ^ rr(w15, 18) ^ (w15 >>> 3))
              + w[i - 7]
              + (rr(w2, 17) ^ rr(w2, 19) ^ (w2 >>> 10))
            ) | 0);
        var temp2 = (rr(a, 2) ^ rr(a, 13) ^ rr(a, 22))
          + ((a & hash[1]) ^ (a & hash[2]) ^ (hash[1] & hash[2]));
        hash = [(temp1 + temp2) | 0].concat(hash);
        hash[4] = (hash[4] + temp1) | 0;
      }
      for (i = 0; i < 8; i++) { hash[i] = (hash[i] + oldHash[i]) | 0; }
    }
    for (i = 0; i < 8; i++) {
      for (j = 3; j + 1; j--) {
        var b = (hash[i] >> (j * 8)) & 255;
        result += ((b < 16) ? 0 : '') + b.toString(16);
      }
    }
    return result;
  }

  return sha256(digits);
}

function() {
  // One normalised shape for every platform mapping below.
  var items = {{DL - ecommerce.items}};
  if (!items || !items.length) { return []; }
  var out = [];
  for (var i = 0; i < items.length; i++) {
    var it = items[i] || {};
    var qty = parseInt(it.quantity, 10);
    if (!qty || qty < 1) { qty = 1; }
    var price = parseFloat(it.price);
    if (isNaN(price)) { price = 0; }
    out.push({
      id: String(it.item_id || it.id || it.sku || ''),
      name: it.item_name || it.name || '',
      category: it.item_category || it.category || '',
      price: Math.round(price * 100) / 100,
      quantity: qty
    });
  }
  return out;
}

function() {
  var items = {{JS - Items (normalised)}}, ids = [];
  for (var i = 0; i < items.length; i++) { if (items[i].id) { ids.push(items[i].id); } }
  return ids;
}

function() {
  var items = {{JS - Items (normalised)}}, out = [];
  for (var i = 0; i < items.length; i++) {
    out.push({ id: items[i].id, quantity: items[i].quantity, item_price: items[i].price });
  }
  return out;
}

function() {
  var items = {{JS - Items (normalised)}};
  return (items.length && items[0].category) ? items[0].category : undefined;
}

function() {
  var items = {{JS - Items (normalised)}}, n = 0;
  for (var i = 0; i < items.length; i++) { n += items[i].quantity; }
  return n || 1;
}

function() {
  var v = {{DL - ecommerce.value}};
  if (v === undefined || v === null || v === '') {
    // No order total on the dataLayer: fall back to the sum of the line items.
    var items = {{JS - Items (normalised)}}, sum = 0;
    for (var i = 0; i < items.length; i++) { sum += items[i].price * items[i].quantity; }
    v = sum;
  }
  var n = parseFloat(String(v).replace(/[^0-9.\-]/g, ''));
  if (isNaN(n) || n < 0) { n = 0; }
  return Math.round(n * 100) / 100;
}

function() {
  var items = {{JS - Items (normalised)}}, ids = [];
  for (var i = 0; i < items.length; i++) { if (items[i].id) { ids.push(items[i].id); } }
  return ids;
}

function() {
  var items = {{JS - Items (normalised)}};
  return items.length ? items[0].name : undefined;
}

function() {
  // The TikTok template JSON.parse()s this field, so hand it a JSON string.
  var items = {{JS - Items (normalised)}}, out = [];
  for (var i = 0; i < items.length; i++) {
    out.push({
      content_id: items[i].id,
      content_type: 'product',
      content_name: items[i].name,
      quantity: items[i].quantity,
      price: items[i].price
    });
  }
  return JSON.stringify(out);
}

function() {
  // Google's enhanced conversions hash the phone in E.164 WITH the leading
  // plus (+966...). Meta, Snap and TikTok hash it WITHOUT. Same number, a
  // completely different digest - so Google needs its own value or it matches
  // nobody.
  //
  // 1) Prefer the hash the Hayak Core plugin computes server-side.
  var u = {{DL - user_data}};
  if (u && typeof u.sha256_phone_number_e164 === 'string' && u.sha256_phone_number_e164.length === 64) {
    return u.sha256_phone_number_e164;
  }
  // 2) Otherwise hash '+' + the normalised phone here, in the browser.
  var digits = {{JS - Phone (normalised)}};
  if (!digits) { return undefined; }

  function sha256(ascii) {
    function rr(v, a) { return (v >>> a) | (v << (32 - a)); }
    var mm = Math.pow, maxWord = mm(2, 32), i, j, result = '';
    var words = [], asciiBitLength = ascii.length * 8;
    var hash = [], k = [], primeCounter = 0, isComposite = {};
    for (var candidate = 2; primeCounter < 64; candidate++) {
      if (!isComposite[candidate]) {
        for (i = 0; i < 313; i += candidate) { isComposite[i] = candidate; }
        hash[primeCounter] = (mm(candidate, 0.5) * maxWord) | 0;
        k[primeCounter++] = (mm(candidate, 1 / 3) * maxWord) | 0;
      }
    }
    ascii += '\x80';
    while (ascii.length % 64 - 56) { ascii += '\x00'; }
    for (i = 0; i < ascii.length; i++) {
      j = ascii.charCodeAt(i);
      if (j >> 8) { return null; }
      words[i >> 2] |= j << ((3 - i) % 4) * 8;
    }
    words[words.length] = (asciiBitLength / maxWord) | 0;
    words[words.length] = asciiBitLength;
    for (j = 0; j < words.length;) {
      var w = words.slice(j, j += 16), oldHash = hash;
      hash = hash.slice(0, 8);
      for (i = 0; i < 64; i++) {
        var w15 = w[i - 15], w2 = w[i - 2];
        var a = hash[0], e = hash[4];
        var temp1 = hash[7]
          + (rr(e, 6) ^ rr(e, 11) ^ rr(e, 25))
          + ((e & hash[5]) ^ ((~e) & hash[6]))
          + k[i]
          + (w[i] = (i < 16) ? w[i] : (
              w[i - 16]
              + (rr(w15, 7) ^ rr(w15, 18) ^ (w15 >>> 3))
              + w[i - 7]
              + (rr(w2, 17) ^ rr(w2, 19) ^ (w2 >>> 10))
            ) | 0);
        var temp2 = (rr(a, 2) ^ rr(a, 13) ^ rr(a, 22))
          + ((a & hash[1]) ^ (a & hash[2]) ^ (hash[1] & hash[2]));
        hash = [(temp1 + temp2) | 0].concat(hash);
        hash[4] = (hash[4] + temp1) | 0;
      }
      for (i = 0; i < 8; i++) { hash[i] = (hash[i] + oldHash[i]) | 0; }
    }
    for (i = 0; i < 8; i++) {
      for (j = 3; j + 1; j--) {
        var b = (hash[i] >> (j * 8)) & 255;
        result += ((b < 16) ? 0 : '') + b.toString(16);
      }
    }
    return result;
  }

  return sha256('+' + digits);
}

